(()=>{
const $=id=>document.getElementById(id);const form=$('builder-form');let html='',data=null,logo='',logoPending=false;
const read=()=>({business:$('business').value.trim(),description:$('description').value.trim(),city:$('city').value.trim(),phone:$('phone').value.trim(),email:$('email').value.trim(),package:$('package').value,theme:$('theme').value,headline:$('headline').value.trim(),services:$('services').value,products:$('products').value,logo});
function status(text,error=false){$('form-status').textContent=text;$('form-status').classList.toggle('error',error);}
function invalidate(){if(data){data=null;html='';$('download').disabled=true;$('review').disabled=true;$('preview-label').textContent='Cambios pendientes de generar';$('review-note').textContent='Genera otra vez para aplicar los cambios y descargar el borrador actualizado.';$('review-status').replaceChildren();}}
form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);
$('package').addEventListener('change',()=>{$('package-note').textContent=$('package').value==='store'?'Catálogo y carrito de demostración. Los pagos reales se configuran después de tu aprobación y la revisión.':'Sitio informativo y catálogo. Los pedidos se coordinan por WhatsApp, sin pagos en la página.';});
form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;if(logoPending){status('Espera a que termine de cargar el logo.',true);return;}const next=read();if(!next.business||!next.description){status('Completa el nombre y la descripción del negocio.',true);return;}const digits=next.phone.replace(/\D/g,'');if(next.phone&&(digits.length<8||digits.length>15)){status('Revisa el WhatsApp e incluye el código de país, por ejemplo +593.',true);return;}try{const result=RDBuilder.generate(next);html=result;data=next;$('preview').srcdoc=html;$('preview-label').textContent=next.business+' · '+(next.package==='store'?'Tienda $350':'Web + catálogo $150');$('download').disabled=false;$('review').disabled=false;$('review-note').textContent='Descarga el archivo HTML. Después solicita la revisión y adjunta el archivo en WhatsApp. Tu página no se publicará automáticamente.';$('review-status').replaceChildren();status('Borrador generado. Puedes cambiar los campos y generar otra versión.');}catch(error){status(error.message,true);}});
$('logo').addEventListener('change',()=>{const file=$('logo').files[0];logo='';$('remove-logo').hidden=true;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){$('logo-status').textContent='Elige una imagen PNG, JPG o WEBP de hasta 2 MB.';$('logo').value='';return;}logoPending=true;const reader=new FileReader();reader.onload=()=>{logo=String(reader.result);logoPending=false;$('logo-status').textContent='Logo listo para el próximo borrador.';$('remove-logo').hidden=false;};reader.onerror=()=>{logoPending=false;$('logo-status').textContent='No se pudo cargar el logo. Prueba otra imagen.';};reader.readAsDataURL(file);});
$('remove-logo').onclick=()=>{logo='';$('logo').value='';$('logo-status').textContent='';$('remove-logo').hidden=true;invalidate();};
function view(mobile){$('preview-frame').classList.toggle('mobile',mobile);$('mobile').setAttribute('aria-pressed',String(mobile));$('desktop').setAttribute('aria-pressed',String(!mobile));}$('mobile').onclick=()=>view(true);$('desktop').onclick=()=>view(false);
$('download').onclick=()=>{if(!html||!data)return;const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(data.business.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9-]/g,'-').slice(0,60)||'mi-web')+'-borrador.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('review').onclick=()=>{if(!data)return;const message='Hola Jordy, generé un borrador en Robalino Digital y quisiera tu revisión.\n\nNegocio: '+data.business+'\nPaquete: '+(data.package==='store'?'Tienda en línea — $350':'Web + catálogo WhatsApp — $150')+'\nCiudad: '+data.city+'\nDescripción: '+data.description+'\n\nAdjuntaré el HTML descargado. Entiendo que aún no está publicado.';const url='https://wa.me/19082403844?text='+encodeURIComponent(message);window.open(url,'_blank','noopener,noreferrer');const note=document.createElement('p');note.textContent='Descarga el borrador y adjúntalo a tu conversación. Para enviar la consulta, pulsa Enviar en WhatsApp.';const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Abrir consulta de revisión';$('review-status').replaceChildren(note,a);};
$('preview').srcdoc=RDBuilder.generate({business:'Tu negocio',description:'Una página clara para presentar lo que haces y conectar con tus clientes. Completa el formulario para crear tu propio borrador.',city:'Vista de ejemplo',headline:'Tu marca comienza aquí.',theme:'electric',package:'catalog',services:'Tu primer servicio\nTu segundo servicio\nTu especialidad',products:'Producto de ejemplo | 10.00'});
})();
